INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(44311, 'Genesis 18:24', 'Genesis', 18, 24, 'که چېرې په دې ښار کې پنځوس تنه نېک خلک وي ایا هغه ښار به په رښتیا له منځه یوسې او هغه ځای به د هغو پنځوسو نېکو خلکو په خاطر پرېنږدې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_24.mp3', '', 1761754199, 1761754199),
(44312, 'Genesis 18:25', 'Genesis', 18, 25, 'زه یقین لرم چې ته به نېک خلک د بدکارانو سره یوځای نه وژنې. دا نه شي کېدای! ته داسې نه شې کولای، که تا داسې وکړل، نو نېکو خلکو ته به د بدکارانو سره یوځای سزا ورکړای شي. دا نه شي کېدای. د ټولې دنیا قاضي به خامخا انصاف کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_25.mp3', '', 1761754199, 1761754199),
(44313, 'Genesis 18:26', 'Genesis', 18, 26, 'څښتن ځواب ورکړ: «که چېرې زه په سدوم کې پنځوس تنه نېک خلک پیدا کړم، نو زه به د هغوی په خاطر ټول ښار معاف کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_26.mp3', '', 1761754199, 1761754199),
(44314, 'Genesis 18:27', 'Genesis', 18, 27, 'ابراهیم یوځل بیا وویل: «څښتنه، ما وبخښه چې ستا سره په جرات سره خبرې کوم. زه یوازې یو عادي انسان یم او حق نه لرم چې څه ووایم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_27.mp3', '', 1761754199, 1761754199),
(44315, 'Genesis 18:28', 'Genesis', 18, 28, 'خو که چېرې هلته د پنځوسو تنو په ځای یوازې پنځه څلوېښت تنه نېک خلک وي، ایا ټول ښار به د هغو پنځو تنو په خاطر چې کم دي، له منځه یوسې؟» څښتن ځواب ورکړ: «که چېرې هلته پنځه څلوېښت تنه نېک خلک پیدا کړم، نو زه به ښار له منځه نه وړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_28.mp3', '', 1761754199, 1761754199),
(44316, 'Genesis 18:29', 'Genesis', 18, 29, 'ابراهیم بیا خبرې وکړې: «کېدای شي چې هلته یوازې څلوېښت تنه وي.» هغه ځواب ورکړ: «زه به د هغو څلوېښتو تنو په خاطر هغه ښار وران نه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_29.mp3', '', 1761754199, 1761754199),
(44317, 'Genesis 18:30', 'Genesis', 18, 30, 'ابراهیم وویل: «څښتنه، په ما باندې په قهر نه شې، اجازه راکړه چې خبرې وکړم. که چېرې هلته یوازې دېرش تنه وي؟» هغه وویل: «که چېرې هلته دېرش تنه پیدا کړم، زه به هغه ځای له منځه نه وړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_30.mp3', '', 1761754199, 1761754199),
(44318, 'Genesis 18:31', 'Genesis', 18, 31, 'ابراهیم وویل: «څښتنه، ما وبخښه چې په جرات سره ستا سره خبرې کوم. که یوازې شل تنه هلته پیدا شي؟» هغه وویل: «که چېرې شل تنه پیدا کړم، زه به ښار وران نه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_31.mp3', '', 1761754199, 1761754199),
(44319, 'Genesis 18:32', 'Genesis', 18, 32, 'ابراهیم وویل: «څښتنه، په ما باندې په قهر نه شې، زه به یوازې یو وار بیا خبرې وکړم. کېدای شي چې لس تنه هلته پیدا شي؟» هغه وویل: «که لس تنه هلته پیدا شي، نو زه به ښار وران نه کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_32.mp3', '', 1761754199, 1761754199),
(44320, 'Genesis 18:33', 'Genesis', 18, 33, 'له هغې وروسته چې څښتن د ابراهیم سره خبرې خلاصې کړې، هغه لاړ او ابراهیم خپل کور ته ستون شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_33.mp3', '', 1761754199, 1761754199),
(44321, 'Psalms 85:1', 'Psalms', 85, 1, 'ای څښتنه تا په خپله خاوره رحم وکړ او یوځل بیا دې رابېدار کړ د یعقوب قسمت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_1.mp3', '', 1761754199, 1761754199),
(44322, 'Psalms 85:2', 'Psalms', 85, 2, 'ودې بخښلې د خپل قوم بدۍ پرده دې واچوله په ټولو ګناهونو د دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_2.mp3', '', 1761754199, 1761754199),
(44323, 'Psalms 85:3', 'Psalms', 85, 3, 'تېر شولې ته له خپل ټول غضبه د خپل قهر اور دې سوړ کړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_3.mp3', '', 1761754199, 1761754199),
(44324, 'Psalms 85:4', 'Psalms', 85, 4, 'ای زمونږ خلاصوونکیه خدایه مونږه بېرته په خپل حال کړه او خپل غضب زمونږ نه لېرې کړه ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_4.mp3', '', 1761754199, 1761754199),
(44325, 'Psalms 85:5', 'Psalms', 85, 5, 'ایا ته به خفه یې تل زمونږ څخه؟ ایا وبه غزوې خپل قهر د یو نسل نه بل نسل ته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_5.mp3', '', 1761754199, 1761754199),
(44326, 'Psalms 85:6', 'Psalms', 85, 6, 'ایا ته به مونږ ته بیا قوت رانه کړې ترڅو ستا قوم خوشحالي وکړي ستا له امله؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_6.mp3', '', 1761754199, 1761754199),
(44327, 'Psalms 85:7', 'Psalms', 85, 7, 'څښتنه، مونږ ته دې وښایه تلپاتې مینه او مونږ ته راکړه خلاصون', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_7.mp3', '', 1761754199, 1761754199),
(44328, 'Psalms 85:8', 'Psalms', 85, 8, 'څښتن خدای چې هرڅه وایي ورته به نیسمه غوږ وعده کوي د سولې خپل وفادار ولس سره خو دوی دې بیا نه راګرځي د حماقت لارو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_8.mp3', '', 1761754199, 1761754199),
(44329, 'Psalms 85:9', 'Psalms', 85, 9, 'بې‌شکه ور به کړي نجات هغوی ته څوک چې ترې وېره لري چې پاتې شي د هغه جلال زمونږ په خاوره کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_9.mp3', '', 1761754199, 1761754199),
(44330, 'Psalms 85:10', 'Psalms', 85, 10, 'څنګه چې دوه تنه یو بل سره ګوري داسې تلپاتې مینه او وفا به سره هم وګوري څنګه چې یو تن بل تن ښکلوي داسې عدالت او سوله به هم یو بل ښکل کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_10.mp3', '', 1761754199, 1761754199),
(44331, 'Psalms 85:11', 'Psalms', 85, 11, 'راپورته کیږي وفا ځمکې نه نېکي راګوري پاس له اسمانه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_11.mp3', '', 1761754199, 1761754199),
(44332, 'Psalms 85:12', 'Psalms', 85, 12, 'ښه شیان مونږ ته راکوي به بې له شکه څښتن ورکوي ښه حاصلات به زمونږ ځمکه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_12.mp3', '', 1761754199, 1761754199),
(44333, 'Psalms 85:13', 'Psalms', 85, 13, 'عدالت به وي روان د څښتن مخکې تیاروي به لار د هغه قدمونو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms85_verse_13.mp3', '', 1761754199, 1761754199),
(44334, 'Esther 9:1', 'Esther', 9, 1, 'د اذر د میاشتې دیارلسمه ورځ، یعنې هغه ورځ چې لومړی شاهي فرمان باید عملي شي راورسېدله، په دې ورځ د یهودیانو دښمنان په دې هیله وو چې په هغوی باندې بریالي شي. خو د دې په ځای، یهودیانو په هغوی باندې بری وموند.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_1.mp3', '', 1761754199, 1761754199),
(44335, 'Esther 9:2', 'Esther', 9, 2, 'یهودیان د خشایار پاچا د امپراتورۍ د ټولو ولایتونو په ټولو ښارونو کې سره راټول شول چې په هغو خلکو باندې حمله وکړي چې غواړي دوی ته زیان ورسوي. هېچا نه شو کولای چې د هغوی په وړاندې ودریږي، ځکه چې د نورو ټولو قومونو خلک د یهودیانو څخه وېرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_2.mp3', '', 1761754199, 1761754199),
(44336, 'Esther 9:3', 'Esther', 9, 3, 'د ولایتونو ټولو مامورینو، د پاچا له خوا ټاکل شویو والیانو، نورو والیانو او شاهي استازو د یهودیانو سره مرسته کوله، ځکه چې هغوی ټول د مردخای څخه وېرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_3.mp3', '', 1761754199, 1761754199),
(44337, 'Esther 9:4', 'Esther', 9, 4, 'مردخای په ماڼۍ کې یو قوي سړی ؤ، په ټولو ولایتونو کې هغه مشهور شو او د وخت په تېرېدلو سره هغه نور هم قوي شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_4.mp3', '', 1761754199, 1761754199),
(44338, 'Esther 9:5', 'Esther', 9, 5, 'نو څه چې د یهودیانو خوښه وه د خپلو دښمنانو سره یې وکړل. خپل ټول دښمنان یې په تورو باندې ووهل، هغوی یې ووژل او له منځه یې یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_5.mp3', '', 1761754199, 1761754199),
(44339, 'Esther 9:6', 'Esther', 9, 6, 'یهودیانو د شوش په بالاحصار کې پنځه سوه کسان ووژل او له منځه یې یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_6.mp3', '', 1761754199, 1761754199),
(44340, 'Esther 9:7', 'Esther', 9, 7, 'همدارنګه هغوی فرشنداطا، دلفون، اسفاتا،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_7.mp3', '', 1761754199, 1761754199),
(44341, 'Esther 9:8', 'Esther', 9, 8, 'فوراتا، ادلیا، اریداتا،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_8.mp3', '', 1761754199, 1761754199),
(44342, 'Esther 9:9', 'Esther', 9, 9, 'فرمشتا، اریسای، اریدای او ویزاتا هم ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_9.mp3', '', 1761754199, 1761754199),
(44343, 'Esther 9:10', 'Esther', 9, 10, 'دا د همداتا د زوی هامان یعنې د یهودیانو د دښمن لس زامن وو. خو هغوی هېڅ شی لوټ نه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_10.mp3', '', 1761754199, 1761754199),
(44344, 'Esther 9:11', 'Esther', 9, 11, 'په هماغه ورځ پاچا ته خبر راورسېد چې د شوش په بالاحصار کې څومره خلک وژل شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_11.mp3', '', 1761754199, 1761754199),
(44345, 'Esther 9:12', 'Esther', 9, 12, 'بیا پاچا استر ملکې ته وویل: «یهودیانو یوازې د شوش په بالاحصار کې پنځه سوه کسان وژلي دي چې په هغو کې د هامان لس زامن هم شامل دي. نو هغوی به د پاچا په نورو ولایتونو څومره خلک وژلي وي؟ اوس ته نور څه غواړې؟ هغه به درکړل شي. ستا نوره غوښتنه څه ده چې زه یې درکړم؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_12.mp3', '', 1761754199, 1761754199),
(44346, 'Esther 9:13', 'Esther', 9, 13, 'استر په ځواب کې وویل: «که ستاسو اعلیحضرت خوښه وي، د شوش یهودیانو ته اجازه ورکړئ چې نننی فرمان دې سبا هم عملي شي او د هامان د لسو زامنو مړي دې په دار باندې وځړول شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_13.mp3', '', 1761754199, 1761754199),
(44347, 'Esther 9:14', 'Esther', 9, 14, 'نو پاچا امر وکړ چې دا وړاندیز دې عملي شي. دا فرمان په شوش کې اعلان شو او د هامان د لسو زامنو مړي په دار باندې وځړول شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_14.mp3', '', 1761754199, 1761754199),
(44348, 'Esther 9:15', 'Esther', 9, 15, 'د شوش یهودیان د اذر د میاشتې په څوارلسمه ورځ د شوش په ښار کې هم راټول شول او درې سوه کسان یې هلته ووژل، خو هغوی هېڅ شی لوټ نه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_15.mp3', '', 1761754199, 1761754199),
(44349, 'Esther 9:16', 'Esther', 9, 16, 'یهودیان په ولایتونو کې هم سره راټول شول چې د خپلو ځانونو څخه دفاع وکړي او د خپلو دښمنانو له شره خلاص شي. هغوی پنځه اویا زره کسان چې د دوی څخه یې کرکه لرله ووژل، خو هېڅ شی یې لوټ نه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_16.mp3', '', 1761754199, 1761754199),
(44350, 'Esther 9:17', 'Esther', 9, 17, 'دا وژنه د اذر د میاشتې په دیارلسمه ورځ وشوه او په څوارلسمه ورځ پوره ارامي وه او دا ورځ یې د خوشحالۍ او جشن ورځ وټاکله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_17.mp3', '', 1761754199, 1761754199),
(44351, 'Esther 9:18', 'Esther', 9, 18, 'خو هغه یهودیان چې په شوش کې وو، په دیارلسمه او څوارلسمه ورځ یې خپل دښمنان ووژل. په پنځلسمه ورځ پوره ارامي وه او په دې ورځ یې جشن ونیوه او خوشحالي یې وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_18.mp3', '', 1761754199, 1761754199),
(44352, 'Esther 9:19', 'Esther', 9, 19, 'له دې امله هغه یهودیان چې د دېوال لرونکو ښارونو دباندې اوسیږي د اذر د میاشتې په څوارلسمه ورځ د خوشحالۍ جشن لمانځي. په دې ورځ هغوی مېلمستیاوې کوي او یو بل ته ډوډۍ د سوغات په توګه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_19.mp3', '', 1761754199, 1761754199),
(44353, 'Esther 9:20', 'Esther', 9, 20, 'مردخای دا ټولې پېښې ولیکلې او د خشایار پاچا د ټولو ولایتونو یهودیانو ته یې که لېرې وو او که نژدې، لیکونه واستول،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_20.mp3', '', 1761754199, 1761754199),
(44354, 'Esther 9:21', 'Esther', 9, 21, 'چې د اذر د میاشتې څوارلسمه او پنځلسمه ورځ باید هر کال ولمانځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_21.mp3', '', 1761754199, 1761754199),
(44355, 'Esther 9:22', 'Esther', 9, 22, 'دا هغه ورځې وې چې یهودیانو د خپلو دښمنانو څخه ارامي وموندله او دا هغه میاشت وه چې د هغوی غم په خوښۍ او ویر یې د خوشحالۍ په جشن بدل شو. هغوی ته وویل شول چې دا ورځې دې په مېلمستیاوو سره ولمانځي او یو بل ته او غریبانو ته ډوډۍ د سوغات په توګه ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_22.mp3', '', 1761754199, 1761754199),
(44356, 'Esther 9:23', 'Esther', 9, 23, 'نو یهودیانو د مردخای د لارښوونو څخه پیروي وکړه او هغوی چې څنګه دا جشن پیل کړی ؤ، هر کال به یې لمانځه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_23.mp3', '', 1761754199, 1761754199),
(44357, 'Esther 9:24', 'Esther', 9, 24, 'هامان د همداتا زوی چې د اجاج د طایفې څخه ؤ او د ټولو یهودیانو دښمن ؤ، پچه اچولې وه (چې هغوی د پوریم په نوم یادوله) او په دې توګه یې د یهودیانو د تباهۍ ورځ ټاکلې وه. هغه دا پلان جوړ کړی ؤ چې هغوی له منځه یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_24.mp3', '', 1761754199, 1761754199),
(44358, 'Esther 9:25', 'Esther', 9, 25, 'خو کله چې دې خبرې ته د پاچا پام شو، نو هغه لیکلی فرمان ورکړ: هغه ناوړه پلان چې هامان د یهودیانو په خلاف سنجولی ؤ هغه دې بېرته په هغه باندې عملي شي او هغه او د هغه زامن دې په دار باندې وځړول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_25.mp3', '', 1761754199, 1761754199),
(44359, 'Esther 9:28', 'Esther', 9, 28, 'دا پرېکړه وشوه چې د هر یو راتلونکي یهودي نسل هره کورنۍ دې په هر ولایت او هر ښار کې چې وي، د پوریم دا ورځې د تل دپاره په یاد وساتي او هغه دې ولمانځي او هغه دې نه هېروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_28.mp3', '', 1761754199, 1761754199),
(44360, 'Esther 9:29', 'Esther', 9, 29, 'نو د ابیحایل لور استر ملکې د مردخای په مرسته د هغه واک په لرلو سره چې هغې درلود، دوهم لیک ولیکه چې د پوریم په اړه لومړنی لیک تایید کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_29.mp3', '', 1761754199, 1761754199),
(44361, 'Esther 9:30', 'Esther', 9, 30, 'دا لیک د ټولو یهودیانو په نامه ؤ او د هغه نقلونه د خشایار پاچا د امپراتورۍ ټولو یوسلو اووه ویشت ولایتونو ته واستول شول. په هغه کې د یهودیانو دپاره د سولې او امنیت غوښتنه شوې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_30.mp3', '', 1761754199, 1761754199),
(44362, 'Esther 9:31', 'Esther', 9, 31, 'هغوی او د هغوی اولادونو ته لارښوونه شوې وه لکه څنګه چې هغوی د روژې نیولو او ویر کولو مراسم په ځای کول، هماغسې دې د پوریم ورځې په ټاکلي وخت ولمانځي. دا امر د یهودي مردخای او استر ملکې له خوا شوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_31.mp3', '', 1761754199, 1761754199),
(44363, 'Esther 9:32', 'Esther', 9, 32, 'د استر فرمان د پوریم قوانین تایید کړل او هغه په یو کتاب کې ولیکل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther9_verse_32.mp3', '', 1761754199, 1761754199),
(44364, 'Exodus 7:1', 'Exodus', 7, 1, 'څښتن موسی ته وویل: «زه به تا فرعون ته لکه د خدای په شان کړم او ستا ورور هارون به ستا د پیغمبر په توګه د هغه سره خبرې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_1.mp3', '', 1761754199, 1761754199),
(44365, 'Exodus 7:2', 'Exodus', 7, 2, 'زه چې تاته د هر شي په اړه حکم کوم، هغه هارون ته ووایه او هغه به فرعون ته ووایي چې اسراییلیان پرېږدي چې د مصر د خاورې څخه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_2.mp3', '', 1761754199, 1761754199),
(44366, 'Exodus 7:5', 'Exodus', 7, 5, 'کله چې زه مصریانو ته خپل قدرت وښایم او اسراییلیان د هغوی له وطنه وباسم، بیا به هغوی پوه شي چې زه څښتن یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_5.mp3', '', 1761754199, 1761754199),
(44367, 'Exodus 7:6', 'Exodus', 7, 6, 'څنګه چې څښتن موسی او هارون ته حکم کړی ؤ، هغوی هماغسې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_6.mp3', '', 1761754199, 1761754199),
(44368, 'Exodus 7:7', 'Exodus', 7, 7, 'هغه وخت چې هغوی د فرعون سره خبرې وکړې، موسی د اتیا کالو او هارون د دري اتیا کالو په عمر ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_7.mp3', '', 1761754199, 1761754199),
(44369, 'Exodus 7:8', 'Exodus', 7, 8, 'څښتن موسی او هارون ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_8.mp3', '', 1761754199, 1761754199),
(44370, 'Exodus 7:9', 'Exodus', 7, 9, '«که چېرې فرعون تاسو ته ووایي چې ماته یوه معجزه وښایئ، بیا هارون ته ووایه چې خپله امسا راواخلي او د فرعون په مخکې یې وغورځوي او هغه به په مار بدله شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_9.mp3', '', 1761754199, 1761754199),
(44371, 'Exodus 7:10', 'Exodus', 7, 10, 'نو موسی او هارون فرعون ته ورغلل او هماغسې یې وکړل څنګه چې څښتن ورته حکم کړی ؤ. هارون خپله امسا د فرعون او د هغه د درباریانو په مخکې وغورځوله او هغه په مار بدله شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_10.mp3', '', 1761754199, 1761754199),
(44372, 'Exodus 7:11', 'Exodus', 7, 11, 'بیا فرعون خپل حکیمان او جادوګران راوغوښتل. هغوی هم د خپلې جادو په وسیله دا کار وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_11.mp3', '', 1761754199, 1761754199),
(44373, 'Exodus 7:12', 'Exodus', 7, 12, 'هغوی هر یو خپلې امساګانې په ځمکه وغورځولې او هغه امساګانې په مارانو بدلې شوې. خو د هارون مار هغه نور ماران روغ تېر کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_12.mp3', '', 1761754199, 1761754199),
(44374, 'Exodus 7:13', 'Exodus', 7, 13, 'بیاهم د فرعون زړه سخت پاتې شو او څنګه چې څښتن ویلي وو، فرعون موسی او هارون ته غوږ ونه نیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_13.mp3', '', 1761754199, 1761754199),
(44375, 'Exodus 7:14', 'Exodus', 7, 14, 'بیا څښتن موسی ته وویل: «د فرعون زړه ډېر سخت دی او د اسراییلو قوم نه پرېږدي چې لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_14.mp3', '', 1761754199, 1761754199),
(44376, 'Exodus 7:15', 'Exodus', 7, 15, 'سهار کله چې فرعون د نیل سیند ته ځي خپله امسا چې په مار بدله شوې وه هغه هم د ځان سره یوسه او د سیند په غاړه هغه ته انتظار وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_15.mp3', '', 1761754199, 1761754199),
(44377, 'Exodus 7:16', 'Exodus', 7, 16, 'بیا هغه ته ووایه: څښتن د عبرانیانو خدای زه رالېږلی یم چې تاته داسې ووایم: زما قوم پرېږده چې دښتې ته لاړ شي او هلته زما عبادت وکړي. خو تر اوسه پورې دې ورته پام نه دی کړی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_16.mp3', '', 1761754199, 1761754199),
(44378, 'Exodus 7:17', 'Exodus', 7, 17, 'اعلیحضرته، څښتن داسې وایي: زه به داسې کار وکړم چې ته پوه شې چې زه څښتن یم. اوس ګوره، دا امسا چې زما په لاس کې ده، په دې به د نیل د سیند اوبه ووهم او هغه به په وینه بدلې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_17.mp3', '', 1761754199, 1761754199),
(44379, 'Exodus 7:18', 'Exodus', 7, 18, 'د سیند ماهیان به مړه شي او د نیل سیند به بد بوی کوي. مصریان به نه شي کولای چې له هغه څخه اوبه وڅښي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_18.mp3', '', 1761754199, 1761754199),
(44380, 'Exodus 7:19', 'Exodus', 7, 19, 'څښتن موسی ته وویل: «هارون ته ووایه چې خپله امسا د ځان سره یوسي او د مصر د اوبو یعنې ویالو، نهرونو او ډنډونو خواته یې ونیسي چې هغه به په وینو بدلې شي. د مصر په هرځای کې به اوبه په وینو باندې بدلې شي، حتی د خلکو په کورونو کې به هم د لرګیو په لوښو او د تیږو په منګیو کې وینه وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_19.mp3', '', 1761754199, 1761754199),
(44381, 'Exodus 7:20', 'Exodus', 7, 20, 'بیا موسی او هارون د څښتن په حکم باندې عمل وکړ. د فرعون او د هغه د درباریانو په حضور کې هارون خپله امسا پورته کړه او د سیند اوبه یې په هغې ووهلې او ټولې اوبه چې په کې وې په وینه بدلې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_20.mp3', '', 1761754199, 1761754199),
(44382, 'Exodus 7:21', 'Exodus', 7, 21, 'د سیند ماهیان مړه شول او سیند دومره ډېر بد بوی کاوه چې مصریانو نه شو کولای چې له هغه څخه اوبه وڅښي. د مصر په هر ځای کې وینه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_21.mp3', '', 1761754199, 1761754199),
(44383, 'Exodus 7:22', 'Exodus', 7, 22, 'بیا د فرعون جادوګرانو هم د خپلې جادو په وسیله همداسې عمل سرته ورساوه او د فرعون زړه د مخکې په شان سخت پاتې شو. لکه څنګه چې څښتن ویلي وو، فرعون د موسی او هارون خبرو ته غوږ ونه نیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_22.mp3', '', 1761754199, 1761754199),
(44384, 'Exodus 7:23', 'Exodus', 7, 23, 'د دې په ځای چې هغه دې خبرې ته پام وکړي، هغه بېرته راستون شو او خپلې ماڼۍ ته لاړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_23.mp3', '', 1761754199, 1761754199),
(44385, 'Exodus 7:24', 'Exodus', 7, 24, 'ټولو مصریانو د نیل د سیند غاړه وکیندله چې د څښلو اوبه راپیدا کړي، ځکه چې هغوی نه شو کولای د سیند اوبه وڅښي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_24.mp3', '', 1761754199, 1761754199),
(44386, 'Exodus 7:25', 'Exodus', 7, 25, 'د هغه وخت څخه چې څښتن د نیل د سیند اوبه په وینه باندې بدلې کړې، پوره اووه ورځې تېرې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus7_verse_25.mp3', '', 1761754199, 1761754199),
(44387, 'Ezekiel 16:1', 'Ezekiel', 16, 1, 'څښتن یوځل بیا ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_1.mp3', '', 1761754199, 1761754199),
(44388, 'Ezekiel 16:2', 'Ezekiel', 16, 2, '«ای فاني انسانه، د اورشلیم خلک د هغوی د کرکې وړ کارونو څخه خبر کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_2.mp3', '', 1761754199, 1761754199),
(44389, 'Ezekiel 16:3', 'Ezekiel', 16, 3, 'اورشلیم ته ووایه چې څښتن تعالی ورته داسې وایي: ‹ستا د زېږېدنې اصلي ځای کنعان دی. ستا پلار اموری ؤ او مور دې حیتۍ وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_3.mp3', '', 1761754199, 1761754199),
(44390, 'Ezekiel 16:4', 'Ezekiel', 16, 4, 'کله چې ته پیدا شوې، نو هېچا ستا نوم غوڅ نه کړ، نه چا ولمبولې، نه یې مالګه درباندې وموښله او نه یې په اورڼي کې تاو کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_4.mp3', '', 1761754199, 1761754199),
(44391, 'Ezekiel 16:5', 'Ezekiel', 16, 5, 'هېچا درباندې رحم ونه کړ. کله چې ته پیدا شوې، نو هېچا په مینه دا کارونه ستا دپاره نه کول، بلکې تاته یې د کرکې په سترګه کتل، نو ته یې د زېږېدلو په وخت کې په صحرا کې وغورځولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel16_verse_5.mp3', '', 1761754199, 1761754199),
